import json,glob,re,collections
FIELD=re.compile(r'("final_answer"\s*:\s*")((?:[^"\\]|\\.)*)(")')
def raw_answer(s):
    for m in reversed(s['messages']):
        if m.get('role')=='assistant' and m.get('content'):
            c=m['content']
            if isinstance(c,list): c=''.join(b.get('text','') for b in c if isinstance(b,dict))
            c=str(c)
            mm=FIELD.search(c)
            if mm: return mm.group(2)
    return None
for r in sorted(glob.glob('/workspace/runs/*')):
    fs=glob.glob(f'{r}/*/conversations/*/sample-*.json')
    if not fs: continue
    c=collections.Counter()
    for f in fs:
        s=json.load(open(f))
        if 'was_correct' not in s: continue
        a=raw_answer(s)
        if a is None: continue
        if a!=s['prediction']:
            c['rewritten']+=1
            if s['was_correct']: c['rewrite_correct']+=1
    if c:
        print(r.split('/')[-1][:8], dict(c))
PY

