import json,glob,collections,os,re
def looks_prose(p, task):
    if task=='USPTO':
        return bool(re.search(r'[\s一-鿿]', p)) 
    if task=='Symptom2Disease':
        return len(p)>60 or ' ' in p.strip() and not re.match(r'^[A-Za-z ,\'\-()]+$', p)
    return len(p)>120
tot=collections.Counter()
for r in sorted(glob.glob('/workspace/runs/*')):
    c=collections.Counter()
    for f in glob.glob(f'{r}/*/conversations/*/sample-*.json'):
        s=json.load(open(f))
        if 'was_correct' not in s: continue
        t=s['task']; p=(s.get('prediction') or '')
        if t=='USPTO' and looks_prose(p,t): c['uspto_prose']+=1
        if t=='LawBench' and p and '[罪名]' not in p: c['law_no_marker']+=1
        if t=='Symptom2Disease' and p and '[DIAGNOSIS]' not in p.upper(): c['sym_no_marker']+=1
    tot.update(c)
    print(os.path.basename(r)[:8], dict(c))
print('TOTAL', dict(tot))
PY

