import json,glob,re,collections
FIELD=re.compile(r'("final_answer"\s*:\s*")((?:[^"\\]|\\.)*)(")')
def answers_in_order(s):
    out=[]
    for m in s['messages']:
        if m.get('role')!='assistant' or not m.get('content'): continue
        c=m['content']
        if isinstance(c,list): c=''.join(b.get('text','') for b in c if isinstance(b,dict))
        mm=FIELD.search(str(c))
        if mm: out.append(mm.group(2))
    return out
agg=collections.Counter()
for r in sorted(glob.glob('/workspace/runs/*')):
    for f in glob.glob(f'{r}/LawBench/conversations/*/sample-*.json'):
        s=json.load(open(f))
        if 'was_correct' not in s: continue
        tc=s.get('tool_calls') or []
        ans=answers_in_order(s)
        agg['n']+=1
        if 'check_answer' in tc:
            agg['checked']+=1; agg['checked_ok']+=int(s['was_correct'])
            if len(ans)>=2 and ans[-1]!=ans[0]:
                agg['changed_after_check']+=1
                agg['changed_after_check_ok']+=int(s['was_correct'])
                agg['changed_before_ok']+=int(ans[0]==s['target'])
        else:
            agg['unchecked']+=1; agg['unchecked_ok']+=int(s['was_correct'])
print(dict(agg))
