import json,glob,re,collections
def first_answer(s):
    for m in s['messages']:
        c=m.get('content')
        txt=None
        if isinstance(c,str) and c.startswith('Q: '): txt=c
        if isinstance(c,list):
            for b in c:
                if isinstance(b,dict) and isinstance(b.get('text'),str) and b['text'].startswith('Q: '): txt=b['text']
        if txt:
            return txt.split('\nA: ',1)[1].split('\n')[0].strip() if '\nA: ' in txt else None
    return None
def norm(t):
    t=t.lower().strip(); t=re.sub(r'\s+',' ',t); return re.sub(r'[.!?]+$','',t)
def pred_label(s):
    p=s['prediction'] or ''
    m=re.search(r'\[DIAGNOSIS\](.*?)\[/DIAGNOSIS\]',p,re.I|re.S)
    if m: return m.group(1).strip()
    m=re.search(r'(?:diagnosis|final diagnosis|conclusion)[:：]\s*([^\n]+)',p,re.I)
    return m.group(1).strip() if m else p.strip()
agg=collections.Counter()
for r in sorted(glob.glob('/workspace/runs/*')):
    for f in glob.glob(f'{r}/Symptom2Disease/conversations/*/sample-*.json'):
        s=json.load(open(f))
        if 'was_correct' not in s: continue
        fa=first_answer(s)
        if fa is None: continue
        pl=pred_label(s)
        agg['n']+=1
        same = norm(pl)==norm(fa)
        if s['was_correct']:
            agg['ok']+=1; agg['ok_pred_eq_first']+=int(same)
        else:
            agg['wrong']+=1; agg['wrong_pred_eq_first']+=int(same)
            if norm(fa)==norm(s['target']): agg['wrong_but_first_is_target']+=1
print(dict(agg))
